/**
 * The one way an icon reaches a screen: `<Icon name="speaker" />`.
 *
 * The set is generated by `npm run icons` from `scripts/icons/icons.config.mjs`
 * (Iconsax free icons under the founder's licence, decision D11, plus a few of
 * Luvani's own). This file is the registry's only reader, so a screen never
 * imports a drawing and swapping a drawing never moves a call site.
 *
 * Linear is for controls and Bulk for tiles, tabs and states. An icon with no
 * Bulk drawing asked for one draws its Linear one rather than nothing. Every
 * icon is decorative: the control around it names what it does, and a screen
 * reader walks past the picture. Still: what moves is `AnimatedIcon`, around a
 * still mark.
 */

import type { ReactElement } from 'react';
import { paper } from '../theme.ts';
import type { IconPaint, IconVariant } from './drawing.ts';
import { ICONS } from './index.ts';
import type { IconName } from './names.ts';

export { SECONDARY_OPACITY } from './drawing.ts';
export type { IconVariant } from './drawing.ts';
export type { BulkIconName, IconName } from './names.ts';

export type IconProps = {
  name: IconName;
  /** Linear (the default) for a control; Bulk for a tile, a focused tab or a state. */
  variant?: IconVariant;
  /** Points. Icons are drawn on a 24 box. */
  size?: number;
  /** The mark. A palette token; ink unless the ground says otherwise. */
  color?: string;
  /** A Bulk icon's soft second layer, drawn at SECONDARY_OPACITY. The mark's own colour unless given. */
  secondaryColor?: string;
};

function paint(size: number, color: string, secondaryColor: string | undefined): IconPaint {
  return { size, color, secondary: secondaryColor ?? color };
}

export function Icon({ name, variant = 'linear', size = 24, color = paper.ink, secondaryColor }: IconProps): ReactElement {
  const drawings = ICONS[name];
  const draw = (variant === 'bulk' ? drawings.bulk : undefined) ?? drawings.linear;
  return draw(paint(size, color, secondaryColor));
}

/**
 * One named part of an icon (a speaker's arc, a lock's shackle), on the same
 * 24 box, so `AnimatedIcon` can stack the parts and move one of them. Stacked,
 * a variant's parts draw exactly the whole icon. A part the icon does not have
 * draws nothing; `icons.test.ts` holds every part `AnimatedIcon` asks for.
 */
export function IconPart({
  name,
  part,
  variant = 'linear',
  size = 24,
  color = paper.ink,
  secondaryColor,
}: IconProps & { part: string }): ReactElement | null {
  const draw = ICONS[name].parts?.[variant]?.[part];
  return draw === undefined ? null : draw(paint(size, color, secondaryColor));
}
